from collections import deque

class MinDFAError(ValueError):
    pass


_EPS = ("eps",)
_EMPTY = ("empty",)
_QUANTIFIERS = frozenset("*+?")


def _validate_alphabet(alphabet: str) -> list[str]:
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    seen = set()
    for ch in alphabet:
        if ch in seen:
            raise ValueError("alphabet contains duplicate characters")
        seen.add(ch)
    return list(alphabet)


def _normalize_concat(parts):
    flat = []
    for p in parts:
        if p is _EMPTY:
            return _EMPTY
        if p is _EPS:
            continue
        if p[0] == "concat":
            flat.extend(p[1])
        else:
            flat.append(p)
    if not flat:
        return _EPS
    if len(flat) == 1:
        return flat[0]
    return ("concat", tuple(flat))


def _normalize_union(parts):
    flat = []
    for p in parts:
        if p is _EMPTY:
            continue
        if p[0] == "union":
            flat.extend(p[1])
        else:
            flat.append(p)

    has_eps = False
    filtered = []
    for p in flat:
        if p is _EPS:
            has_eps = True
        elif p is not _EMPTY:
            filtered.append(p)

    if has_eps:
        if not filtered:
            return _EPS
        return ("union", tuple([_EPS] + filtered))
    if not filtered:
        return _EMPTY
    if len(filtered) == 1:
        return filtered[0]
    return ("union", tuple(filtered))


def _make_star(a):
    if a is _EPS:
        return _EPS
    if a is _EMPTY:
        return _EPS
    if a[0] == "star":
        return a
    if a[0] == "plus":
        return a
    return ("star", a)


def _make_plus(a):
    if a is _EPS:
        return _EPS
    if a is _EMPTY:
        return _EMPTY
    if a[0] == "star":
        return a
    if a[0] == "plus":
        return a
    if a[0] == "opt":
        return _make_star(a[1])
    return ("plus", a)


def _make_opt(a):
    if a is _EPS:
        return _EPS
    if a is _EMPTY:
        return _EPS
    if a[0] == "opt":
        return a
    if a[0] == "star":
        return a
    if a[0] == "plus":
        return _make_star(a[1])
    return ("opt", a)


class _Parser:
    def __init__(self, pattern: str, alphabet: str):
        self.s = pattern
        self.n = len(pattern)
        self.alphabet = alphabet
        self.alpha_set = set(alphabet)

    def _read_one_literal(self, i: int):
        if i >= self.n:
            raise ValueError("pattern ends with a dangling escape")
        ch = self.s[i]
        if ch == "\\":
            if i + 1 >= self.n:
                raise ValueError("pattern ends with a dangling escape")
            return self.s[i + 1], i + 2
        return ch, i + 1

    def _parse_alternation(self, i: int, in_group: bool):
        alts = []
        while True:
            node, i = self._parse_concat(i, in_group)
            alts.append(node)
            if i < self.n and self.s[i] == "|":
                i += 1
                continue
            break

        if i >= self.n and in_group:
            raise ValueError("unmatched '('")

        if not in_group and i < self.n and self.s[i] == ")":
            raise ValueError("unmatched ')'")

        if len(alts) == 1:
            return alts[0], i
        return _normalize_union(alts), i

    def _parse_concat(self, i: int, in_group: bool):
        parts = []
        while i < self.n:
            ch = self.s[i]
            if ch == "|":
                break
            if in_group and ch == ")":
                break
            if ch in _QUANTIFIERS:
                raise ValueError("quantifier without a preceding element")

            node, i = self._parse_element(i)
            parts.append(node)

            if i < self.n and self.s[i] in _QUANTIFIERS:
                raise ValueError("stacked quantifier")

        return _normalize_concat(parts), i

    def _parse_element(self, i: int):
        node, i = self._parse_atom(i)
        if i < self.n and self.s[i] in _QUANTIFIERS:
            q = self.s[i]
            i += 1
            if q == "*":
                node = _make_star(node)
            elif q == "+":
                node = _make_plus(node)
            else:
                node = _make_opt(node)
        return node, i

    def _parse_atom(self, i: int):
        if i >= self.n:
            raise ValueError("unexpected end of pattern")

        ch = self.s[i]

        if ch == ")":
            raise ValueError("unmatched ')'")

        if ch == "(":
            i += 1
            node, i = self._parse_alternation(i, True)
            if i >= self.n or self.s[i] != ")":
                raise ValueError("unmatched '('")
            i += 1
            return node, i

        if ch == "[":
            return self._parse_char_class(i)

        if ch == "\\":
            lit, i = self._read_one_literal(i)
            return self._literal_node(lit), i

        if ch == ".":
            return ("dot",), i + 1

        return self._literal_node(ch), i + 1

    def _literal_node(self, ch: str):
        return ("lit", ch) if ch in self.alpha_set else _EMPTY

    def _char_to_lit(self, ch: str):
        return ("lit", ch) if ch in self.alpha_set else _EMPTY

    def _parse_char_class(self, i: int):
        assert self.s[i] == "["
        i += 1

        negate = False
        if i < self.n and self.s[i] == "^":
            negate = True
            i += 1

        selected = set()
        has_item = False

        while True:
            if i >= self.n:
                raise ValueError("unterminated character class")

            if self.s[i] == "]":
                if not has_item:
                    raise ValueError("empty character class")
                i += 1
                break

            has_item = True

            x, ni = self._read_one_literal(i)

            if x == "-":
                selected.add(x)
                i = ni
                continue

            if ni < self.n and self.s[ni] == "-":
                after_dash = ni + 1

                if after_dash < self.n and self.s[after_dash] == "]":
                    selected.add(x)
                    i = ni
                    continue

                if after_dash >= self.n:
                    selected.add(x)
                    i = ni
                    continue

                y, after = self._read_one_literal(after_dash)
                if ord(x) > ord(y):
                    raise ValueError("invalid character range")

                for c in self.alphabet:
                    if ord(x) <= ord(c) <= ord(y):
                        selected.add(c)

                i = after
                continue

            selected.add(x)
            i = ni

        if negate:
            selected = set(self.alphabet) - selected
        else:
            selected = selected & self.alpha_set

        if not selected:
            return _EMPTY, i

        if len(selected) == 1:
            ch = next(iter(selected))
            return self._literal_node(ch), i

        return ("class", frozenset(selected)), i


def _parse_pattern(pattern: str, alphabet: str):
    parser = _Parser(pattern, alphabet)
    ast, i = parser._parse_alternation(0, False)
    if i != len(pattern):
        raise ValueError("unmatched parentheses")
    return ast


class _NFA:
    def __init__(self, alphabet: str):
        self.alpha = list(alphabet)
        self.alpha_index = {ch: idx for idx, ch in enumerate(self.alpha)}
        self.eps = []
        self.trans = []  # trans[state][symbol_idx] -> list[int]
        self.final = -1

    def new_state(self):
        idx = len(self.eps)
        self.eps.append([])
        self.trans.append([[] for _ in self.alpha])
        return idx

    def add_eps(self, a, b):
        self.eps[a].append(b)

    def add_trans(self, a, sym_idx, b):
        self.trans[a][sym_idx].append(b)

    def empty_fragment(self):
        s = self.new_state()
        e = self.new_state()
        return s, e

    def epsilon_fragment(self):
        s = self.new_state()
        return s, s

    def literal_fragment(self, ch):
        sym_idx = self.alpha_index.get(ch)
        if sym_idx is None:
            return self.empty_fragment()
        s = self.new_state()
        e = self.new_state()
        self.add_trans(s, sym_idx, e)
        return s, e

    def dot_fragment(self):
        s = self.new_state()
        e = self.new_state()
        for idx in range(len(self.alpha)):
            self.add_trans(s, idx, e)
        return s, e

    def class_fragment(self, chars):
        chars = frozenset(c for c in chars if c in self.alpha_index)
        if not chars:
            return self.empty_fragment()
        s = self.new_state()
        e = self.new_state()
        for ch in chars:
            self.add_trans(s, self.alpha_index[ch], e)
        return s, e

    def union(self, frags):
        if not frags:
            return self.empty_fragment()
        ns = self.new_state()
        ne = self.new_state()
        for s, e in frags:
            self.add_eps(ns, s)
            self.add_eps(e, ne)
        return ns, ne

    def concat(self, frags):
        if not frags:
            return self.epsilon_fragment()
        if len(frags) == 1:
            return frags[0]
        ns, ne = frags[0]
        for prev, nxt in zip(frags, frags[1:]):
            self.add_eps(prev[1], nxt[0])
        return ns, ne

    def star(self, frag):
        ns = self.new_state()
        ne = self.new_state()
        s, e = frag
        self.add_eps(ns, s)
        self.add_eps(ns, ne)
        self.add_eps(e, s)
        self.add_eps(e, ne)
        return ns, ne

    def plus(self, frag):
        ns = self.new_state()
        ne = self.new_state()
        s, e = frag
        self.add_eps(ns, s)
        self.add_eps(e, s)
        self.add_eps(e, ne)
        return ns, ne

    def optional(self, frag):
        ns = self.new_state()
        ne = self.new_state()
        s, e = frag
        self.add_eps(ns, s)
        self.add_eps(ns, ne)
        self.add_eps(e, ne)
        return ns, ne

    def compile(self, ast):
        kind = ast[0]

        if kind == "eps":
            return self.epsilon_fragment()
        if kind == "empty":
            return self.empty_fragment()
        if kind == "lit":
            return self.literal_fragment(ast[1])
        if kind == "dot":
            return self.dot_fragment()
        if kind == "class":
            return self.class_fragment(ast[1])

        if kind == "union":
            frags = [self.compile(x) for x in ast[1]]
            return self.union(frags)

        if kind == "concat":
            frags = [self.compile(x) for x in ast[1]]
            return self.concat(frags)

        if kind == "star":
            frag = self.compile(ast[1])
            return self.star(frag)

        if kind == "plus":
            frag = self.compile(ast[1])
            return self.plus(frag)

        if kind == "opt":
            frag = self.compile(ast[1])
            return self.optional(frag)

        raise ValueError("bad AST node")


class _MinimizeError(Exception):
    pass


def _build_dfa_from_pattern(pattern: str, alphabet: str):
    alpha = _validate_alphabet(alphabet)
    ast = _parse_pattern(pattern, alpha)

    nfa = _NFA(alpha)
    start, final = nfa.compile(ast)
    nfa.final = final

    n_states = len(nfa.eps)

    eps_closure_state = [0] * n_states
    for i in range(n_states):
        stack = [i]
        mask = 0
        seen = set()
        while stack:
            v = stack.pop()
            bit = 1 << v
            if bit & mask:
                continue
            mask |= bit
            seen.add(v)
            for b in nfa.eps[v]:
                if b not in seen:
                    stack.append(b)
        eps_closure_state[i] = mask

    def closure(mask: int):
        result = 0
        m = mask
        while m:
            lb = m & -m
            idx = lb.bit_length() - 1
            result |= eps_closure_state[idx]
            m ^= lb
        return result

    trans_state = []
    for i in range(n_states):
        masks = []
        for sym in range(len(alpha)):
            m = 0
            for v in nfa.trans[i][sym]:
                m |= 1 << v
            masks.append(m)
        trans_state.append(masks)

    def move(mask: int, sym: int):
        moved = 0
        m = mask
        while m:
            lb = m & -m
            idx = lb.bit_length() - 1
            moved |= trans_state[idx][sym]
            m ^= lb
        return closure(moved)

    final_bit = 1 << final if final >= 0 else 0

    start_mask = closure(1 << start if start >= 0 else 0)

    mask_to_id = {}
    states = []
    transitions = []
    accepting = []

    def add_state(mask: int):
        if mask in mask_to_id:
            return mask_to_id[mask]
        sid = len(states)
        mask_to_id[mask] = sid
        states.append(mask)
        transitions.append([None] * len(alpha))
        accepting.append(bool(mask & final_bit))
        return sid

    start_id = add_state(start_mask)
    queue = deque([start_id])

    while queue:
        sid = queue.popleft()
        mask = states[sid]
        for sym in range(len(alpha)):
            nxt = move(mask, sym)
            nid = add_state(nxt)
            transitions[sid][sym] = nid
            if nxt not in mask_to_id:
                pass
            elif transitions[nid][0] is None and nxt != start_mask:
                # It was newly created; still in queue via add_state? We need ensure queue.
                pass
            if nid == len(states) - 1 and mask_to_id.get(nxt) == nid:
                queue.append(nid)

    # Ensure completeness and queue every created state once.
    created = set(range(len(states)))
    queue = deque()
    for sid in created:
        if sid != start_id:
            queue.append(sid)
    # If some transition target was not queued, BFS again over ids.
    again = deque([start_id])
    visited_ids = {start_id}
    while again:
        sid = again.popleft()
        for sym in range(len(alpha)):
            nxt = transitions[sid][sym]
            if nxt is None:
                mask = move(states[sid], sym)
                nxt = add_state(mask)
                transitions[sid][sym] = nxt
            if nxt not in visited_ids:
                visited_ids.add(nxt)
                again.append(nxt)

    return transitions, accepting, len(alpha)


def _minimize_dfa(transitions, accepting, alpha_len):
    n = len(transitions)
    if n <= 1:
        return n

    accepts = [i for i, a in enumerate(accepting) if a]
    nonaccepts = [i for i, a in enumerate(accepting) if not a]

    blocks = []
    color = [-1] * n

    if accepts:
        blocks.append(accepts)
        for s in accepts:
            color[s] = len(blocks) - 1
    if nonaccepts:
        blocks.append(nonaccepts)
        for s in nonaccepts:
            color[s] = len(blocks) - 1

    inv = [[[] for _ in range(n)] for _ in range(alpha_len)]
    for s in range(n):
        for c in range(alpha_len):
            inv[c][transitions[s][c]].append(s)

    work = deque()
    in_work = set()

    for b in range(len(blocks)):
        work.append(b)
        in_work.add(b)

    while work:
        b = work.popleft()
        in_work.discard(b)
        if b >= len(blocks):
            continue
        target_block = blocks[b]
        if not target_block:
            continue

        for c in range(alpha_len):
            split = set()
            for target in target_block:
                for src in inv[c][target]:
                    split.add(src)
            if not split:
                continue

            snapshot = list(range(len(blocks)))
            for p in snapshot:
                blk = blocks[p]
                if not blk:
                    continue
                part_in = [x for x in blk if x in split]
                part_out = [x for x in blk if x not in split]
                if not part_in or not part_out:
                    continue

                blocks[p] = part_out
                q = len(blocks)
                blocks.append(part_in)

                for x in part_out:
                    color[x] = p
                for x in part_in:
                    color[x] = q

                if p not in in_work:
                    in_work.add(p)
                    work.append(p)
                if q not in in_work:
                    in_work.add(q)
                    work.append(q)

        target_block = blocks[b] if b < len(blocks) else None

    return len([x for x in blocks if x])


def _dfa_object(pattern: str, alphabet: str):
    trans, acc, alpha_len = _build_dfa_from_pattern(pattern, alphabet)
    minimized_count = _minimize_dfa(trans, acc, alpha_len)
    return trans, acc, alpha_len, minimized_count


def _min_dfa_size(pattern: str, alphabet: str) -> int:
    _trans, _acc, _alpha_len, count = _dfa_object(pattern, alphabet)
    return count


def _minimized_dfa_representative(pattern: str, alphabet: str):
    trans, acc, alpha_len, _count = _dfa_object(pattern, alphabet)

    n = len(trans)
    if n <= 1:
        # Return a single state, with self loops.
        new_trans = [[0] * alpha_len]
        new_acc = [acc[0] if n else False]
        return new_trans, new_acc, alpha_len

    blocks = [[] for _ in range(n)]
    representative = [-1] * n

    # Build blocks from a stable partition: use minimization partition implicitly.
    # Re-run partition refinement to get a block id for each old state.
    accepts = [i for i, a in enumerate(acc) if a]
    nonaccepts = [i for i, a in enumerate(acc) if not a]
    parts = []
    color = [-1] * n
    if accepts:
        parts.append(accepts)
        for s in accepts:
            color[s] = len(parts) - 1
    if nonaccepts:
        parts.append(nonaccepts)
        for s in nonaccepts:
            color[s] = len(parts) - 1

    inv = [[[] for _ in range(n)] for _ in range(alpha_len)]
    for s in range(n):
        for c in range(alpha_len):
            inv[c][trans[s][c]].append(s)

    work = deque()
    in_work = set()
    for b in range(len(parts)):
        work.append(b)
        in_work.add(b)

    while work:
        b = work.popleft()
        in_work.discard(b)
        if b >= len(parts) or not parts[b]:
            continue
        target_block = parts[b]

        for c in range(alpha_len):
            split = set()
            for target in target_block:
                for src in inv[c][target]:
                    split.add(src)
            if not split:
                continue

            snapshot = list(range(len(parts)))
            for p in snapshot:
                blk = parts[p]
                if not blk:
                    continue
                part_in = [x for x in blk if x in split]
                part_out = [x for x in blk if x not in split]
                if not part_in or not part_out:
                    continue

                parts[p] = part_out
                q = len(parts)
                parts.append(part_in)
                for x in part_out:
                    color[x] = p
                for x in part_in:
                    color[x] = q
                if p not in in_work:
                    in_work.add(p)
                    work.append(p)
                if q not in in_work:
                    in_work.add(q)
                    work.append(q)

    live_parts = []
    part_id_to_new = {}
    for i, blk in enumerate(parts):
        if not blk:
            continue
        # Sort old states deterministically for stable construction.
        blk_sorted = sorted(blk)
        new_id = len(live_parts)
        part_id_to_new[i] = new_id
        rep = blk_sorted[0]
        representative[rep] = new_id
        live_parts.append((blk_sorted, rep))

    new_n = len(live_parts)
    new_trans = [[0] * alpha_len for _ in range(new_n)]
    new_acc = [False] * new_n

    for new_id, (blk_sorted, _rep) in enumerate(live_parts):
        old_rep = blk_sorted[0]
        new_acc[new_id] = acc[old_rep]
        for c in range(alpha_len):
            old_target = trans[old_rep][c]
            old_part_id = color[old_target]
            new_trans[new_id][c] = part_id_to_new[old_part_id]

    return new_trans, new_acc, alpha_len


def distinguish(p1: str, p2: str, alphabet: str):
    alpha = _validate_alphabet(alphabet)

    d1, a1, _ = _minimized_dfa_representative(p1, alpha)
    d2, a2, _ = _minimized_dfa_representative(p2, alpha)

    # BFS in the product DFA. States are pairs (s1, s2).
    # Alphabet order is given by alphabet order.
    start = (0, 0)

    if a1[0] != a2[0]:
        return ""

    # Encoded state for visited set.
    n1, n2 = len(d1), len(d2)
    def enc(s1, s2):
        return s1 * n2 + s2

    start_enc = enc(0, 0)
    visited = {start_enc}
    parent = {start_enc: (-1, -1)}
    parent_word = {start_enc: ""}

    q = deque()
    q.append((0, 0))

    found_enc = None
    found_word = None

    while q:
        s1, s2 = q.popleft()
        e = enc(s1, s2)
        current_word = parent_word[e]

        for ch in alpha:
            c = alpha.index(ch) if False else _char_index(alpha, ch)
            t1 = d1[s1][c]
            t2 = d2[s2][c]
            ne = enc(t1, t2)
            if ne in visited:
                continue

            visited.add(ne)
            new_word = current_word + ch
            parent[ne] = (e, c)
            parent_word[ne] = new_word

            if a1[t1] != a2[t2]:
                return new_word

            q.append((t1, t2))

    return None


def _char_index(alphabet: str, ch: str):
    # alphabet is small (<=8); this is fine and avoids building a map outside helper.
    for i, x in enumerate(alphabet):
        if x == ch:
            return i
    return -1
